"""Demo data: one account per role, categories, artifacts, an exhibition with slots and ticket types, knowledge base."""
import sys
from datetime import date, timedelta
from .app import create_app
from .db import q, x, local_now
from .security import hash_password, encrypt, new_totp_secret

# Demo 3D models (generated by tools/gen_models.py) for the seeded exhibits: title -> (file, size MB, overlay text)
DEMO_MODELS = {"Bronze Age Mask": ("mask", "Cast bronze, c. 1200 BC"), "Gold Ring": ("ring", "Gold ring with a garnet-coloured stone, c. 300 BC"),
               "Woven Sadu Panel": ("sadu", "Bedouin sadu weaving in wool"), "Embroidered Kandura": ("kandura", "Silk-thread embroidery, Liwa"),
               "Pearl Diver's Gear": ("pearl", "Basket, nose clip and a pearl"), "Dhow Model": ("dhow", "Wooden trading dhow"),
               "Calligraphy Panel": ("calligraphy", "Ink and gold calligraphy"), "Oil Landscape": ("landscape", "Desert landscape in oils")}

def add_demo_models(app):
    """Attach a published 3D model to every seeded exhibit that has none yet (idempotent; safe on an existing smms.db)."""
    import os
    n = 0
    with app.app_context():
        for title, (name, overlay) in DEMO_MODELS.items():
            a = q("SELECT artifact_id FROM artifact WHERE title=?", (title,), one=True)
            path = os.path.join(app.static_folder, "models", name + ".glb")
            if not a or not os.path.exists(path) or q("SELECT 1 FROM ar_content WHERE artifact_id=?", (a["artifact_id"],), one=True): continue
            x("INSERT INTO ar_content(artifact_id,model_url,file_size_mb,overlay_text,published,updated_at) VALUES (?,?,?,?,1,datetime('now'))",
              (a["artifact_id"], f"/static/models/{name}.glb", round(os.path.getsize(path) / 1048576, 2), overlay)); n += 1
    return n

def seed(app):
    with app.app_context():
        if q("SELECT 1 FROM account LIMIT 1", one=True): return {}
        secrets_ = {}
        def acct(email, role, pw="Passw0rd1", mfa=False):
            s = new_totp_secret() if mfa else None
            aid = x("INSERT INTO account(email,password_hash,role,is_active,email_verified,mfa_enabled,mfa_secret) VALUES (?,?,?,?,?,?,?)", (email, hash_password(pw), role, 1, 1, 1 if mfa else 0, s))
            secrets_[email] = s; return aid
        v = acct("visitor@smms.example", "Visitor")
        x("INSERT INTO visitor(visitor_id,display_name,preferred_language,consent_personalisation) VALUES (?,?,?,1)", (v, "Demo Visitor", "EN"))
        x("INSERT INTO interest_profile(visitor_id,updated_at) VALUES (?,datetime('now'))", (v,))
        s = acct("staff@smms.example", "Staff", mfa=True); x("INSERT INTO staff(staff_id,full_name,department) VALUES (?,?,?)", (s, "Demo Staff", "Collections"))
        m = acct("manager@smms.example", "Manager", mfa=True); x("INSERT INTO manager(manager_id,full_name) VALUES (?,?)", (m, "Demo Manager"))
        a = acct("admin@smms.example", "ITAdmin", mfa=True); x("INSERT INTO it_admin(admin_id) VALUES (?)", (a,))
        cats = {n: x("INSERT INTO category(name) VALUES (?)", (n,)) for n in ("Archaeology", "Textiles", "Maritime", "Art")}
        arts = [("Bronze Age Mask", "Archaeology", "Ceremonial bronze mask with incised decoration found near Al Ain", "c. 1200 BC", "Al Ain", "Gallery 1"),
                ("Gold Ring", "Archaeology", "Gold ring from an ancient burial, archaeology collection", "c. 300 BC", "Mleiha", "Gallery 1"),
                ("Woven Sadu Panel", "Textiles", "Traditional Bedouin sadu weaving in wool, textile craft", "19th century", "Abu Dhabi", "Gallery 2"),
                ("Embroidered Kandura", "Textiles", "Hand embroidered textile garment with silk thread", "20th century", "Liwa", "Gallery 2"),
                ("Pearl Diver's Gear", "Maritime", "Pearl diving equipment, nose clip and basket, maritime trade history", "19th century", "Gulf", "Gallery 3"),
                ("Dhow Model", "Maritime", "Wooden dhow ship model, maritime trade routes", "20th century", "Sharjah", "Gallery 3"),
                ("Calligraphy Panel", "Art", "Arabic calligraphy painting in ink and gold", "18th century", "Cairo", "Gallery 4"),
                ("Oil Landscape", "Art", "Oil painting of a desert landscape", "20th century", "Dubai", "Gallery 4")]
        ids = []
        for t, c, d, p, o, loc in arts:
            ids.append(x("""INSERT INTO artifact(title,category_id,description,period,origin,condition,location,status,qr_code_value,created_by,updated_at)
                            VALUES (?,?,?,?,?,'good',?,'onDisplay',?,?,datetime('now'))""", (t, cats[c], d, p, o, loc, f"ART-DEMO{len(ids):02d}", s)))
        today = local_now().date()
        e = x("INSERT INTO exhibition(title,gallery,start_date,end_date,description) VALUES (?,?,?,?,?)", ("Gulf Heritage Gallery", "Level 1", str(today), str(today + timedelta(days=180)), "Heritage of the Gulf"))
        for aid in ids: x("INSERT INTO exhibition_item(exhibition_id,artifact_id,display_start_date,display_end_date) VALUES (?,?,?,?)", (e, aid, str(today), str(today + timedelta(days=180))))
        for n, pr in (("Adult", 30), ("Child", 15), ("Student", 20)): x("INSERT INTO ticket_type(exhibition_id,name,price) VALUES (?,?,?)", (e, n, pr))
        for d_ in range(0, 7):
            for st, en in (("10:00", "11:00"), ("11:00", "12:00"), ("13:00", "14:00")):
                x("INSERT INTO time_slot(exhibition_id,slot_date,start_time,end_time,capacity) VALUES (?,?,?,?,?)", (e, str(today + timedelta(days=d_)), st, en, 20))
        kb = [("What are the opening hours?", "The museum is open daily from 10:00 to 18:00.", "Visitor info > Opening hours"),
              ("Is the museum wheelchair accessible?", "Yes. All galleries are step free and lifts serve every floor. Wheelchairs can be borrowed at the information desk.", "Visitor info > Accessibility"),
              ("How much are tickets?", "Adult tickets cost 30 AED, child tickets 15 AED and student tickets 20 AED.", "Tickets"),
              ("Can I take photographs?", "Photography without flash is allowed in all galleries.", "Visitor info > Photography")]
        for qn, an, src in kb:
            x("INSERT INTO knowledge_entry(question,answer,language,status,source_page,updated_by,updated_at) VALUES (?,?,?,'published',?,?,datetime('now'))", (qn, an, "EN", src, s))
        x("INSERT INTO ar_content(artifact_id,model_url,file_size_mb,overlay_text,published,updated_at) VALUES (?,?,?,?,1,datetime('now'))", (ids[0], "/static/models/mask.glb", 8.5, "Cast bronze, c. 1200 BC", ))
        return secrets_

if __name__ == "__main__":
    app = create_app(); sec = seed(app)
    print("3D models attached to", add_demo_models(app), "exhibits")
    print("Demo accounts (password Passw0rd1):")
    for k, v in sec.items(): print(" ", k, "TOTP secret:", v or "-")
